const now = new Date().toISOString();
const baseUrl = ($env.RS_CANONICAL_BASE_URL || 'https://rsperformance.online').replace(/\/$/, '');
const token = $env.N8N_API_TOKEN || $env.RS_API_TOKEN || '';
if (!String(token).trim()) {
  throw new Error('SEO Search Ops harvester: set RS_API_TOKEN or N8N_API_TOKEN in n8n environment (X-API-Token for hosting Search Ops API).');
}

return [
  {
    json: {
      source: 'gsc',
      days: 28,
      limit: 25,
      baseUrl,
      token,
      runLabel: 'weekly-harvest',
      startedAt: now,
    },
  },
  {
    json: {
      source: 'bing',
      days: 28,
      limit: 25,
      baseUrl,
      token,
      runLabel: 'weekly-harvest',
      startedAt: now,
    },
  },
];

const items = $input.all();
const lines = [];
let storedTotal = 0;
let okCount = 0;
let failCount = 0;

for (const item of items) {
  const source = item.json.source || item.json.body?.source || 'unknown';
  const status = item.json.status || item.json.body?.status || 'error';
  const stored = Number(item.json.stored || item.json.body?.stored || 0);
  const statusCode = item.json.statusCode || item.json.code || 200;
  const ok = status === 'ok' && statusCode >= 200 && statusCode < 300;

  if (ok) {
    okCount += 1;
    storedTotal += stored;
  } else {
    failCount += 1;
  }

  lines.push(`${ok ? 'OK' : 'FAIL'} ${source}: stored=${stored} code=${statusCode}`);
}

return [{
  json: {
    status: failCount === 0 ? 'ok' : 'warning',
    storedTotal,
    okCount,
    failCount,
    checkedAt: new Date().toISOString(),
    report: lines.join('\n'),
  },
}];
